"""Tests for the ERRANT stdout parsers and the metric definitions.

The parser tests run against a **captured golden fixture** rather than shelling
out to ERRANT, which keeps them fast. The real safety net in production is
``evaluate.errant_scores``, which cross-checks every parsed score against
:func:`gec.evaluate.score_m2_pure_python` and raises if they disagree.
"""

from __future__ import annotations

import pytest

from gec import evaluate, m2, paths

#: A REAL `errant_compare -hyp ... -ref ... -cat 2` capture, regenerated by
#: scripts/make_golden_fixture.py. It is read from disk rather than inlined so
#: the test genuinely guards against ERRANT changing its output format.
#:
#: (An earlier version of this fixture was hand-written and its F-score column
#: was internally inconsistent, which made three tests assert wrong numbers.
#: Capture, do not invent.)
FIXTURES = paths.TESTS / "fixtures"
GOLDEN = paths.read_text(FIXTURES / "errant_compare_cat2.txt")


def test_parse_categories():
    rows = evaluate.parse_errant_categories(GOLDEN)
    by = {r["category"]: r for r in rows}
    assert set(by) == {"DET", "NOUN:INFL", "PREP", "VERB:FORM", "VERB:SVA", "VERB:TENSE"}
    assert (by["VERB:SVA"]["tp"], by["VERB:SVA"]["fp"], by["VERB:SVA"]["fn"]) == (1, 2, 0)
    assert by["VERB:SVA"]["f05"] == pytest.approx(0.3846)
    assert (by["PREP"]["tp"], by["PREP"]["fn"]) == (0, 2)
    # support = tp + fn is the gold frequency figure 6 needs.
    assert by["PREP"]["support"] == 2
    assert by["DET"]["f05"] == pytest.approx(1.0)
    # -cat 2 strips the M:/U:/R: prefix.
    assert not any(c.startswith(("M:", "U:", "R:")) for c in by)


def test_parse_categories_never_splits_a_category_name():
    """-cat 2 strips M:/U:/R:, so names have no spaces and split() gives 7 fields."""
    for r in evaluate.parse_errant_categories(GOLDEN):
        assert " " not in r["category"]


def test_parse_overall():
    o = evaluate.parse_errant_overall(GOLDEN)
    assert (o["tp"], o["fp"], o["fn"]) == (2, 2, 5)
    assert o["precision"] == pytest.approx(0.5)
    assert o["recall"] == pytest.approx(0.2857)
    assert o["f05"] == pytest.approx(0.4348)


def test_our_f_beta_reproduces_the_golden_overall_row():
    """Our f_beta must agree with the numbers ERRANT itself printed."""
    o = evaluate.parse_errant_overall(GOLDEN)
    p, r, f = evaluate.f_beta(o["tp"], o["fp"], o["fn"])
    assert (p, r, f) == (o["precision"], o["recall"], o["f05"])


def test_our_f_beta_reproduces_every_golden_category_row():
    for row in evaluate.parse_errant_categories(GOLDEN):
        p, r, f = evaluate.f_beta(row["tp"], row["fp"], row["fn"])
        assert (p, r, f) == (row["p"], row["r"], row["f05"]), row["category"]


def test_pure_python_scorer_matches_the_golden_capture():
    """The cross-check that makes the parsers self-validating, on real M2 files."""
    o = evaluate.parse_errant_overall(GOLDEN)
    s = evaluate.score_m2_pure_python(FIXTURES / "golden_hyp.m2",
                                      FIXTURES / "golden_ref.m2")
    assert (s["tp"], s["fp"], s["fn"]) == (o["tp"], o["fp"], o["fn"])
    assert abs(s["f05"] - o["f05"]) < 0.005


def test_parsers_raise_on_unrecognised_output():
    """A format change must fail loudly, not return silently wrong numbers."""
    with pytest.raises(evaluate.ErrantParseError):
        evaluate.parse_errant_categories("some unrelated text")
    with pytest.raises(evaluate.ErrantParseError):
        evaluate.parse_errant_overall("some unrelated text")


def test_parse_overall_tolerates_a_truncated_value_line():
    truncated = "TP\tFP\tFN\tPrec\tRec\tF0.5\n"
    with pytest.raises(evaluate.ErrantParseError):
        evaluate.parse_errant_overall(truncated)


# --------------------------------------------------------------------------- #
# f_beta must match ERRANT's computeFScore exactly
# --------------------------------------------------------------------------- #

def test_f_beta_matches_errant_conventions():
    # An empty hypothesis set: no FP -> P defined as 1.0. This is why the E0
    # copy baseline reports P = 1.0 with F0.5 = 0.
    p, r, f = evaluate.f_beta(0, 0, 100)
    assert (p, r, f) == (1.0, 0.0, 0.0)
    # Perfect
    assert evaluate.f_beta(10, 0, 0) == (1.0, 1.0, 1.0)
    # Hand-checked: p = 0.6, r = 12/43 = 0.27907,
    # F0.5 = 1.25 * 0.6 * 0.27907 / (0.25 * 0.6 + 0.27907) = 0.48781
    assert evaluate.f_beta(12, 8, 31) == (0.6, 0.2791, 0.4878)


def test_f_beta_rounds_to_four_places():
    """ERRANT rounds inside its own tie-break search, so we must too."""
    for args in [(12, 8, 31), (46, 53, 230), (1, 2, 0), (2, 2, 5)]:
        for v in evaluate.f_beta(*args):
            assert v == round(v, 4)


def test_f_beta_beta_weights_precision():
    """F0.5 weights precision above recall."""
    _, _, f05 = evaluate.f_beta(10, 5, 50, beta=0.5)
    _, _, f2 = evaluate.f_beta(10, 5, 50, beta=2.0)
    assert f05 > f2


# --------------------------------------------------------------------------- #
# The independent scorer must agree with ERRANT's algorithm
# --------------------------------------------------------------------------- #

def _write(path, text):
    with open(path, "w", encoding="utf-8", newline="\n") as fh:
        fh.write(text)


def test_pure_python_scorer_perfect_match(tmp_path):
    block = ("S He go to school .\n"
             "A 1 2|||R:VERB:SVA|||goes|||REQUIRED|||-NONE-|||0\n\n")
    hyp, ref = tmp_path / "h.m2", tmp_path / "r.m2"
    _write(hyp, block)
    _write(ref, block)
    s = evaluate.score_m2_pure_python(hyp, ref)
    assert (s["tp"], s["fp"], s["fn"]) == (1, 0, 0)
    assert s["f05"] == 1.0


def test_pure_python_scorer_ignores_the_category(tmp_path):
    """ERRANT's default mode keys on (start, end, cor) WITHOUT the category.

    Including the category would be -cse mode and would score this as a miss.
    """
    _write(tmp_path / "h.m2",
           "S He go to school .\nA 1 2|||R:VERB:TENSE|||goes|||REQUIRED|||-NONE-|||0\n\n")
    _write(tmp_path / "r.m2",
           "S He go to school .\nA 1 2|||R:VERB:SVA|||goes|||REQUIRED|||-NONE-|||0\n\n")
    s = evaluate.score_m2_pure_python(tmp_path / "h.m2", tmp_path / "r.m2")
    assert s["tp"] == 1, "same span and correction, different label -> still a TP"


def test_pure_python_scorer_counts_fp_and_fn(tmp_path):
    _write(tmp_path / "h.m2",
           "S He go to school .\nA 3 4|||R:NOUN|||college|||REQUIRED|||-NONE-|||0\n\n")
    _write(tmp_path / "r.m2",
           "S He go to school .\nA 1 2|||R:VERB:SVA|||goes|||REQUIRED|||-NONE-|||0\n\n")
    s = evaluate.score_m2_pure_python(tmp_path / "h.m2", tmp_path / "r.m2")
    assert (s["tp"], s["fp"], s["fn"]) == (0, 1, 1)


def test_pure_python_scorer_noop_is_never_tp_fp_or_fn(tmp_path):
    noop = ("S He goes to school .\n"
            "A -1 -1|||noop|||-NONE-|||REQUIRED|||-NONE-|||0\n\n")
    _write(tmp_path / "h.m2", noop)
    _write(tmp_path / "r.m2", noop)
    s = evaluate.score_m2_pure_python(tmp_path / "h.m2", tmp_path / "r.m2")
    assert (s["tp"], s["fp"], s["fn"]) == (0, 0, 0)


def test_pure_python_scorer_copy_baseline_gives_zero_f05(tmp_path):
    """The E0 property, at the level of the scorer."""
    _write(tmp_path / "h.m2",
           "S He go to school .\nA -1 -1|||noop|||-NONE-|||REQUIRED|||-NONE-|||0\n\n")
    _write(tmp_path / "r.m2",
           "S He go to school .\nA 1 2|||R:VERB:SVA|||goes|||REQUIRED|||-NONE-|||0\n\n")
    s = evaluate.score_m2_pure_python(tmp_path / "h.m2", tmp_path / "r.m2")
    assert s["f05"] == 0.0
    assert s["precision"] == 1.0, "no FP -> ERRANT reports P = 1.0"
    assert s["fn"] == 1


def test_pure_python_scorer_picks_the_better_annotator(tmp_path):
    """With two references, the hypothesis is scored against the kinder one."""
    _write(tmp_path / "h.m2",
           "S We discussed about the plan .\n"
           "A 2 3|||U:PREP||||||REQUIRED|||-NONE-|||0\n\n")
    _write(tmp_path / "r.m2",
           "S We discussed about the plan .\n"
           "A 1 2|||R:VERB|||talked|||REQUIRED|||-NONE-|||1\n"
           "A 2 3|||U:PREP||||||REQUIRED|||-NONE-|||0\n\n")
    s = evaluate.score_m2_pure_python(tmp_path / "h.m2", tmp_path / "r.m2")
    assert s["tp"] == 1 and s["fp"] == 0


def test_pure_python_scorer_rejects_misaligned_files(tmp_path):
    _write(tmp_path / "h.m2", "S one .\nA -1 -1|||noop|||-NONE-|||REQUIRED|||-NONE-|||0\n\n")
    _write(tmp_path / "r.m2",
           "S one .\nA -1 -1|||noop|||-NONE-|||REQUIRED|||-NONE-|||0\n\n"
           "S two .\nA -1 -1|||noop|||-NONE-|||REQUIRED|||-NONE-|||0\n\n")
    with pytest.raises(AssertionError, match="block mismatch"):
        evaluate.score_m2_pure_python(tmp_path / "h.m2", tmp_path / "r.m2")


# --------------------------------------------------------------------------- #
# Metric definitions
# --------------------------------------------------------------------------- #

def test_over_correction_counts_only_already_correct_sentences():
    srcs = ["a b c", "d e f", "g h i"]
    hyps = ["a b c", "d e X", "g h Y"]      # changed #2 and #3
    clean = [True, True, False]              # only #1 and #2 were already correct
    out = evaluate.over_correction(srcs, hyps, clean)
    assert out["n_clean"] == 2
    assert out["n_clean_changed"] == 1       # #2 only; #3 is not a clean sentence
    assert out["over_correction_rate"] == 0.5


def test_over_correction_with_no_clean_sentences():
    out = evaluate.over_correction(["a"], ["b"], [False])
    assert out["over_correction_rate"] is None
    assert out["n_clean"] == 0


def test_over_correction_ignores_whitespace_differences():
    out = evaluate.over_correction(["a  b"], ["a b"], [True])
    assert out["n_clean_changed"] == 0, "compared on .split(), not raw strings"


def test_copy_rate():
    assert evaluate.copy_rate(["a b", "c d"], ["a b", "x y"]) == 0.5
    assert evaluate.copy_rate([], []) == 0.0


def test_bleu_reports_both_tokenisations():
    hyps = ["He goes to school ."] * 4
    refs = [["He goes to school ."]] * 4
    out = evaluate.bleu_scores(hyps, refs)
    assert out["bleu_13a"] == pytest.approx(100.0, abs=1e-6)
    assert out["bleu_tok"] == pytest.approx(100.0, abs=1e-6)
    assert out["n_refs"] == 1


def test_bleu_excludes_sentences_with_no_usable_reference():
    """A handful of W&I annotations delete the whole sentence.

    The kept sentence must be long enough to contain 4-grams, or corpus BLEU is
    legitimately 0 regardless of the exclusion logic.
    """
    hyps = ["He goes to school every day .", "anything at all here"]
    refs = [["He goes to school every day ."], [""]]
    out = evaluate.bleu_scores(hyps, refs)
    assert out["n_bleu_excluded"] == 1
    assert out["bleu_13a"] == pytest.approx(100.0, abs=1e-6)


def test_bleu_returns_none_when_nothing_is_scoreable():
    out = evaluate.bleu_scores(["x"], [[""]])
    assert out["bleu_13a"] is None and out["n_bleu_excluded"] == 1


def test_avg_edits_per_sentence(tmp_path):
    p = tmp_path / "h.m2"
    _write(p,
           "S a b c\nA 0 1|||R:OTHER|||x|||REQUIRED|||-NONE-|||0\n"
           "A 2 3|||R:OTHER|||y|||REQUIRED|||-NONE-|||0\n\n"
           "S d e f\nA -1 -1|||noop|||-NONE-|||REQUIRED|||-NONE-|||0\n\n")
    assert evaluate.avg_edits_per_sentence(p) == 1.0   # (2 + 0) / 2


def test_reference_m2_prefers_a_run_local_file(tmp_path):
    """The smoke plan writes a sliced reference into the run directory."""
    run = tmp_path / "seed13"
    (run / "predictions").mkdir(parents=True)
    local = run / "predictions" / "val.ref.m2"
    _write(local, "S x .\nA -1 -1|||noop|||-NONE-|||REQUIRED|||-NONE-|||0\n\n")
    assert evaluate.reference_m2("val", run) == local
